package javax.microedition.lcdui;
public final class Font {public static final int FACE_SYSTEM=0,FACE_MONOSPACE=32,FACE_PROPORTIONAL=64,STYLE_PLAIN=0,STYLE_BOLD=1,STYLE_ITALIC=2,STYLE_UNDERLINED=4,SIZE_SMALL=8,SIZE_MEDIUM=0,SIZE_LARGE=16,FONT_STATIC_TEXT=0,FONT_INPUT_TEXT=1;private static final Font DEFAULT=new Font(0,0,0);final int scale;private final int face,style,size;
 private Font(int face,int style,int size){this.face=face;this.style=style;this.size=size;scale=size==SIZE_LARGE?2:1;}public static Font getFont(int face,int style,int size){return new Font(face,style,size);}public static Font getFont(int spec){return getDefaultFont();}public static Font getDefaultFont(){return DEFAULT;}public int getHeight(){return scale*12;}public int getBaselinePosition(){return scale*8;}public int charWidth(char c){return 8*scale;}public int charsWidth(char[]c,int o,int n){return n*8*scale;}public int stringWidth(String s){return s.length()*8*scale;}public int substringWidth(String s,int o,int n){return n*8*scale;}public int getFace(){return face;}public int getStyle(){return style;}public int getSize(){return size;}public boolean isPlain(){return style==0;}public boolean isBold(){return (style&1)!=0;}public boolean isItalic(){return (style&2)!=0;}public boolean isUnderlined(){return (style&4)!=0;}}
